// Mapuje typ żaluzji (jt) na kolumnę dostępności tasiemki
export function jzTasWidthGroup(jt){
  if(jt==="al35"||jt==="ba35"||jt==="bs35")return "z35";
  if(jt==="al50"||jt==="ba50"||jt==="bs50")return "z50";
  if(jt==="ba65"||jt==="bs65")return "z65";
  return null;
}

