export function formatPLN(n){return roundTo10(n).toLocaleString("pl-PL")+" zł";}
export function roundTo10(n){var r=n%10;return r<5?n-r:n+(10-r);}

export function getPDFOfferNumber(client){
  var now=new Date();
  var y=now.getFullYear();
  var m=String(now.getMonth()+1).padStart(2,"0");
  var d=String(now.getDate()).padStart(2,"0");
  var slug=(client.name||"").replace(/\s+/g,"-").slice(0,12);
  return "OF-"+y+m+d+"-"+slug;
}

// Zwraca czytelny opis szczegółów produktu (tkanina/kolor/kolor lameli/kolor karnisza)
// używany we wszystkich PDF-ach ofertowych (Wycena PDF, Wycena Uproszczona, Oferta).
export function productDetailText(p){
  var pc=p.c||{};
  var parts=[];
  // Tkanina + kolor: zasłony, firany, rolety rzymskie (w tym Duo — obie warstwy)
  if(p.type==="zaslona"||p.type==="firana"||p.type==="roleta"){
    var fab=p.fabName||p.fabManName||null;
    if(fab)parts.push(fab+(pc.kolor?" ("+pc.kolor+")":""));
    if(pc.rModel==="duo"&&(p.fab2Name||p.fab2ManName)){
      parts.push((p.fab2Name||p.fab2ManName)+(pc.kolor2?" ("+pc.kolor2+")":""));
    }
  }
  // Żaluzje: kolor lameli
  if(p.type==="zaluzja"){
    var jt=pc.jt||"al25";
    var list=jt.indexOf("al")===0?JZ_AL50_COLORS:jt==="ba50"?JZ_BA50_COLORS:jt==="bs50"?JZ_BS50_COLORS:null;
    if(list&&pc.jzColor){
      var cObj=list.find(function(c){return c.v===pc.jzColor;});
      if(cObj)parts.push("kolor lameli: "+cObj.l);
    }
  }
  // Karnisz dekoracyjny: kolor
  if(p.type==="karnisz_dek"&&p.kdKolor){
    var kd=KD_KOLORY.find(function(k){return k.id===p.kdKolor;});
    if(kd)parts.push("kolor: "+kd.label);
  }
  // Roleta rzymska: kolor łańcuszka (jeśli metalowy)
  if(p.type==="roleta"&&pc.lancuszek==="metalowy"&&pc.kolorLancuszka){
    parts.push("\u0142a\u0144cuszek: "+pc.kolorLancuszka);
  }
  return parts.join(" / ");
}

export function buildOfferRows(client){
  // Returns [{lp, name, qty, unit, cenaJedn, total}]
  function escOffer(s){return String(s).replace(/</g,"&lt;");}
  var rows=[];var lp=1;
  (client.rooms||[]).forEach(function(r){
    (r.windows||[]).forEach(function(w){
      (w.products||[]).forEach(function(p){
        var pfc=(p.type==="zaslona"||p.type==="firana")?mg(p,{panels:getPanelsForProd(p)}):p;
        var total=p.mp!=null?p.mp:(calc(pfc).total||0);
        if(!total)return;
        var lbl=(PROD_TYPES.find(function(t){return t.id===p.type;})||{label:p.type}).label;
        var prodLabel=p.type==="inny"?(p.innyNazwa||lbl):lbl;
        var detail=productDetailText(p);
        var desc=prodLabel+(detail?" \u00b7 "+detail:"")+" — "+r.name+(w.name?" / "+w.name:"")
          +(p.note?"<br><span style=\"font-size:9px;color:#a86b00;font-style:italic;\">Uwaga: "+escOffer(p.note)+"</span>":"");
        var isKurtain=(p.type==="zaslona"||p.type==="firana");
        rows.push({lp:lp++,name:desc,qty:1,unit:isKurtain?"kpl.":"szt.",cenaJedn:total,total:total});
      });
    });
  });
  return rows;
}

// Wiersze "Wyceny szczegółowej" — jak buildOfferRows (wszystkie typy produktów),
// ale z dodatkowymi kolumnami technicznymi analogicznymi do zlecenia szycia
// (Model szycia / Tkanina i Kolor / Producent / Szerokość / Wysokość / Podział).
// Nazwa produktu NIE zawiera uwag (p.note) — te idą wyłącznie do wspólnego pola
// "Uwagi do wyceny" na dole dokumentu, nie do opisu pozycji.
export function buildOfferDetailRows(client){
  var rows=[];
  (client.rooms||[]).forEach(function(r){
    (r.windows||[]).forEach(function(w){
      (w.products||[]).forEach(function(p){
        var pc=p.c||{},par=p.par||{};
        var pfc=(p.type==="zaslona"||p.type==="firana")?mg(p,{panels:getPanelsForProd(p)}):p;
        var total=p.mp!=null?p.mp:(calc(pfc).total||0);
        if(!total)return;
        var lbl=(PROD_TYPES.find(function(t){return t.id===p.type;})||{label:p.type}).label;
        var prodLabel=p.type==="inny"?(p.innyNazwa||lbl):lbl;
        var isKurtain=(p.type==="zaslona"||p.type==="firana");
        var nameLoc=" — "+r.name+(w.name?" / "+w.name:"");
        var name=prodLabel+nameLoc;

        var modelSzycia="-",tkaninaKolor="-",producent="-",szerokosc="-",wysokosc="-",podzial="-";

        if(isKurtain){
          var sz;
          if(pc.model==="wave"||pc.sz==="wave"){sz="Wave";}
          else if(pc.model==="falda"){
            var foldMap={pojedyncza:"Flex I",podwojna:"Flex II",potrojna:"Flex III",plaska:"Fa\u0142da P\u0142aska",studio:"Fa\u0142da Studio"};
            sz=pc.foldType?foldMap[pc.foldType]||("Fa\u0142da "+pc.foldType):"Fa\u0142da";
          } else if(pc.model==="tasma"){sz=pc.typMarszczenia||"Smok";}
          else{sz="Flex";}
          var mars=pc.mars?(Math.round(+pc.mars*100))+"%":"150%";
          modelSzycia=sz+" "+mars;
          var fabObj=p.fabName?FABRICS.find(function(f){return f.name===p.fabName;}):null;
          tkaninaKolor=(p.fabName||p.fabManName||"tkanina")+(pc.kolor?" / "+pc.kolor:"");
          producent=fabObj?fabObj.prod:"-";
          szerokosc=par.wCm?(par.wCm+" cm"):"-";
          wysokosc=par.hCm?(par.hCm+" cm"):"-";
          var split=pc.split||"unequal";
          if(split==="left")podzial="Lewa";
          else if(split==="right")podzial="Prawa";
          else if(split==="equal"){var tw=par.wCm||0;podzial="Kurtyna "+Math.floor(tw/2)+" + "+Math.ceil(tw/2)+" cm";}
          else podzial=(pc.leftW||0)+"cm + "+(pc.rightW||0)+"cm";
        } else if(p.type==="roleta"){
          var rModelMap={relax:"Relax",print:"Print",back:"Back",front:"Front",cascade:"Cascade",duo:"Duo"};
          modelSzycia=rModelMap[pc.rModel]||pc.rModel||"-";
          var fabObjR=p.fabName?FABRICS.find(function(f){return f.name===p.fabName;}):null;
          var rLancuszekKolorMap={srebrny:"Srebrny",zloty:"Z\u0142oty",stare_zloto:"Stare z\u0142oto",antracyt:"Antracyt",miedz:"Mied\u017a"};
          var rLancuszekLbl=pc.rSystem==="elektryk"?null
            :(pc.lancuszek==="metalowy"
              ?"\u0142a\u0144cuszek "+(rLancuszekKolorMap[pc.kolorLancuszka]||"srebrny").toLowerCase()
              :"\u0142a\u0144cuszek bia\u0142y");
          tkaninaKolor=(p.fabName||p.fabManName||"tkanina")+(pc.kolor?" / "+pc.kolor:"")+(rLancuszekLbl?" / "+rLancuszekLbl:"");
          producent=fabObjR?fabObjR.prod:"-";
          szerokosc=par.wCm?(par.wCm+" cm"):"-";
          wysokosc=par.hCm?(par.hCm+" cm"):"-";
          podzial=pc.rSystem==="elektryk"?(pc.stronaSilnika||"Lewo")
            :(pc.rModel==="duo"&&pc.rSystem==="manual"?"Obie strony":(pc.stronaObslugi||"Lewo"));
        } else if(p.type==="zaluzja"){
          // Producent \u017caluzji jest zawsze ten sam \u2014 Sun & Shade
          producent="Sun & Shade";
          var jzT=pc.jt||"al25";
          modelSzycia=JZ_LABELS[jzT]||jzT;
          var jzList=jzT.indexOf("al")===0?JZ_AL50_COLORS:jzT.indexOf("ba")===0?JZ_BA50_COLORS:jzT.indexOf("bs")===0?JZ_BS50_COLORS:null;
          var jzCol=(jzList&&pc.jzColor)?jzList.find(function(col){return col.v===pc.jzColor;}):null;
          var jzParts=[];
          if(jzCol)jzParts.push(jzCol.l+(jzCol.code?" ("+jzCol.code+")":""));
          if(pc.tasiemka==="tak"){
            var jzTas=pc.tasiemkaColor?JZ_TASIEMKA_COLORS.find(function(col){return col.v===pc.tasiemkaColor;}):null;
            jzParts.push(jzTas?("tasiemka: "+jzTas.l+(jzTas.code?" ("+jzTas.code+")":"")):"tasiemka");
          }
          tkaninaKolor=jzParts.length?jzParts.join(" / "):"-";
          szerokosc=par.wCm?(par.wCm+" cm"):"-";
          wysokosc=par.lCm?(par.lCm+" cm"):"-";
          podzial=pc.jzStrona||"Lewo";
        } else if(p.type==="szyna"){
          modelSzycia=pc.ks==="wave"?"Wave":"Flex";
          tkaninaKolor=pc.ks==="wave"?(pc.kk==="czarna"?"Czarna":"Bia\u0142a"):"-";
          szerokosc=par.len?(par.len+" cm"):"-";
          // Szyny KS \u2014 producent zawsze Forest
          producent=p.karniszSupplier||"Forest";
        } else if(p.type==="karnisz"||p.type==="prestige_round"||p.type==="prestige_square"){
          szerokosc=par.len?(par.len+" cm"):"-";
          producent=p.karniszSupplier||"-";
        } else if(p.type==="plisa"){
          // Plisy okienne \u2014 producent zawsze Hanarol
          producent="Hanarol";
          var plColl=PLISA_FABRICS.find(function(f){return f.name===pc.plKolekcja;});
          modelSzycia=plColl?plColl.name:(pc.plKolekcjaManual||"-");
          var plKolorLbl=pc.plKolorKod||pc.plKolorManual||"-";
          var plOspCol=PLISA_OSPRZET_KOLORY.find(function(k){return k.v===pc.plKolorOsprzetu;});
          tkaninaKolor=plKolorLbl+(plOspCol?" / osprz\u0119t: "+plOspCol.l:"");
          szerokosc=par.wMm?(Math.round(par.wMm/10)+" cm"):"-";
          wysokosc=par.hMm?(Math.round(par.hMm/10)+" cm"):"-";
        }

        rows.push({
          room:r.name,win:w.name,
          qty:1,unit:isKurtain?"kpl.":"szt.",
          name:name,_prodLabel:prodLabel,_nameLoc:nameLoc,
          modelSzycia:modelSzycia,tkaninaKolor:tkaninaKolor,producent:producent,
          szerokosc:szerokosc,wysokosc:wysokosc,podzial:podzial,
          total:total,cenaJedn:total
        });
      });
    });
  });

  // Numerowanie powt\u00f3rze\u0144 \u2014 gdy kilka produkt\u00f3w tego samego typu trafia do tego samego
  // pomieszczenia/okna (albo do okien bez nazwy), wiersze wygl\u0105da\u0142yby identycznie. Numer
  // wstawiamy po etykiecie produktu ("\u017baluzje 1 \u2014 Gabinet"), analogicznie do chip\u00f3w na
  // ekranie okna. Numerujemy wy\u0142\u0105cznie realne duplikaty \u2014 pojedyncze pozycje zostaj\u0105 bez numeru.
  var nameCount={};
  rows.forEach(function(x){nameCount[x.name]=(nameCount[x.name]||0)+1;});
  var nameSeen={};
  rows.forEach(function(x){
    var key=x.name;
    if(nameCount[key]>1){
      nameSeen[key]=(nameSeen[key]||0)+1;
      x.name=x._prodLabel+" "+nameSeen[key]+x._nameLoc;
    }
    delete x._prodLabel;delete x._nameLoc;
  });
  return rows;
}


export function buildFabricRows(client){
  // One row per window: {prod, fabName, kolor, width, metry, room, win, note}
  // Obsługuje: zaslona, firana, roleta (w tym Duo)
  var rows=[];
  (client.rooms||[]).forEach(function(r){
    (r.windows||[]).forEach(function(w){
      (w.products||[]).forEach(function(p){
        var pc=p.c||{};
        // ── zasłony i firany ─────────────────────────────────────────
        if(p.type==="zaslona"||p.type==="firana"){
          var panels=getPanelsForProd(p);
          var pForCalc=Object.assign({},p,{panels:panels});
          var res=calc(pForCalc);
          var metry=0;
          (res.lines||[]).forEach(function(l){
            var m=l.match(/([\d,.]+)mb/);if(m)metry+=parseFloat(m[1].replace(",","."));
          });
          rows.push({
            fabName:p.fabName||(p.fabManName||"tkanina"),
            prod:p.fabName?(FABRICS.find(function(f){return f.name===p.fabName;})||{prod:"-"}).prod:"-",
            kolor:pc.kolor||"-",
            brutto:p.fabMan||p.fabP||0,
            width:p.fabW||null,
            metry:metry,
            room:r.name,
            win:w.name,
            note:p.note||""
          });
          return;
        }
        // ── rolety rzymskie ───────────────────────────────────────
        if(p.type==="roleta"){
          var par=p.par||{};
          var isBezMech=pc.rSystem==="bez_mechanizmu";
          var rWcm=isBezMech?(par.wCm||0)+30:(par.wCm||0)+20;
          var rTunele=isBezMech?0:Math.floor((par.hCm||0)/23);
          var rHcm=isBezMech?(par.hCm||0):(par.hCm||0)+5+10+rTunele*2;
          var rMetry=parseFloat(((rWcm/100)*(rHcm/100)).toFixed(3));
          var fabObj=p.fabName?FABRICS.find(function(f){return f.name===p.fabName;}):null;
          rows.push({
            fabName:p.fabName||(p.fabManName||"tkanina"),
            prod:fabObj?fabObj.prod:"-",
            kolor:pc.kolor||"-",
            brutto:p.fabMan||p.fabP||0,
            width:p.fabW||null,
            metry:rMetry,
            room:r.name,
            win:w.name,
            note:"Roleta"+(p.note?" — "+p.note:"")
          });
          // Roleta Duo — druga warstwa tkaniny
          if(pc.rModel==="duo"&&(p.fab2Name||p.fab2ManName)){
            var fab2Obj=p.fab2Name?FABRICS.find(function(f){return f.name===p.fab2Name;}):null;
            rows.push({
              fabName:p.fab2Name||(p.fab2ManName||"tkanina"),
              prod:fab2Obj?fab2Obj.prod:"-",
              kolor:pc.kolor2||"-",
              brutto:p.fab2Man||p.fab2P||0,
              width:p.fab2W||null,
              metry:rMetry,
              room:r.name,
              win:w.name,
              note:"Roleta Duo (warstwa 2)"+(p.note?" — "+p.note:"")
            });
          }
          return;
        }
      });
    });
  });
  return rows;
}

export function getPanelsForProd(prod){
  var pc=prod.c||{},par=prod.par||{},tw=par.wCm||0,sp=pc.split||"unequal";
  if(sp==="left") return [{side:"Zas\u0142ona lewa",w:tw}];
  if(sp==="right") return [{side:"Zas\u0142ona prawa",w:tw}];
  if(sp==="equal"){var h=Math.floor(tw/2);return [{side:"Zas\u0142ona lewa",w:h},{side:"Zas\u0142ona prawa",w:tw-h}];}
  var out=[];
  if(pc.leftW>0) out.push({side:"Zas\u0142ona lewa",w:pc.leftW});
  if(pc.rightW>0) out.push({side:"Zas\u0142ona prawa",w:pc.rightW});
  return out;
}

export function buildSewingRows(client){
  var rows=[];
  (client.rooms||[]).forEach(function(r){
    (r.windows||[]).forEach(function(w){
      (w.products||[]).forEach(function(prod){
        if(prod.type!=="zaslona"&&prod.type!=="firana"&&prod.type!=="roleta")return;
        var pc=prod.c||{},par=prod.par||{};
        var lbl=(PROD_TYPES.find(function(t){return t.id===prod.type;})||{label:prod.type}).label;
        var lblDisp=prod.type==="inny"?(prod.innyNazwa||lbl):lbl;
        var fabObj=prod.fabName?FABRICS.find(function(f){return f.name===prod.fabName;}):null;

        if(prod.type==="roleta"){
          var isBezMech=pc.rSystem==="bez_mechanizmu";
          var rWcm=isBezMech?(par.wCm||0)+30:(par.wCm||0)+20;
          var rTunele=isBezMech?0:Math.floor((par.hCm||0)/23);
          var rHcm=isBezMech?(par.hCm||0):(par.hCm||0)+5+10+rTunele*2;
          var rMetry=parseFloat(((rWcm/100)*(rHcm/100)).toFixed(3));
          var rModelMap={relax:"Relax",print:"Print",back:"Back",front:"Front",cascade:"Cascade",duo:"Duo"};
          var rModelLbl=rModelMap[pc.rModel]||pc.rModel||"-";
          if(pc.rModel==="duo"&&pc.rDuoModel){
            rModelLbl+=" \u2013 "+(rModelMap[pc.rDuoModel]||pc.rDuoModel);
          }
          var rLancuszek=pc.lancuszek==="metalowy"
            ?"Metalowy"+(pc.kolorLancuszka?" ("+pc.kolorLancuszka+")":"")
            :"Biały";
          var // elektryk: stronaSilnika | manual Duo: obie strony | półautomat/manual: stronaObslugi
          rStrona=pc.rSystem==="elektryk"?(pc.stronaSilnika||"Lewo"):(pc.rModel==="duo"&&pc.rSystem==="manual"?"Obie strony":(pc.stronaObslugi||"Lewo"));
          var fab2Obj=prod.fab2Name?FABRICS.find(function(f){return f.name===prod.fab2Name;}):null;
          var fabricDesc=prod.fabName||(prod.fabManName||"tkanina");
          if(pc.rModel==="duo"){
            var fab2Desc=prod.fab2Name||(prod.fab2ManName||"tkanina");
            fabricDesc="\u2460 "+fabricDesc+" / \u2461 "+fab2Desc;
          }
          rows.push({
            room:r.name,win:w.name,
            type:lblDisp+" ("+rModelLbl+")",
            fabric:fabricDesc,
            prod:fabObj?fabObj.prod:"-",
            fabW:prod.fabW||prod.fabManW||"-",
            kolor:(pc.rModel==="duo"&&pc.kolor2)?("\u2460 "+(pc.kolor||"-")+" / \u2461 "+pc.kolor2):(pc.kolor||"-"),
            wCm:par.wCm||null,
            hCm:par.hCm||null,
            nadprozeCm:par.hNadproza||"-",
            boczki:pc.rMask==="tak"?"TAK":"nie",
            podszewka:pc.rPodszewka==="tak"?"TAK":"nie",
            rSystem:pc.rSystem==="elektryk"?"elektryczny":pc.rSystem==="polautomatyczny"?"półautomatyczny":"manualny",
            stronaObslugi:rStrona,
            lancuszek:pc.rSystem==="elektryk"?"-":pc.rSystem==="bez_mechanizmu"?"":rLancuszek,
            kolorLancuszka:(function(){
              if(pc.rSystem==="elektryk"||pc.rSystem==="bez_mechanizmu")return "-";
              if(pc.lancuszek==="bialy")return "Biały";
              var km={srebrny:"Srebrny",zloty:"Złoty",stare_zloto:"Stare złoto",antracyt:"Antracyt",miedz:"Miedź"};
              return km[pc.kolorLancuszka]||"Srebrny";
            })(),
            tasmaNaStojaco:"-",
            szStyle:"-",marszczenie:"-",tasma:"-",haczyk:"-",
            split:"-",bottom:"-",glide:"-",leadInSides:"-",
            _type:"roleta",
            note:prod.note||""
          });
          return;
        }


        var panels=getPanelsForProd(prod);
        var prodForCalc=Object.assign({},prod,{panels:panels});
        var res=calc(prodForCalc);
        var metry=0;
        (res.lines||[]).forEach(function(l){
          var m=l.match(/([\d,.]+)mb/);if(m)metry+=parseFloat(m[1].replace(",","."));
        });
        var sz;
        if(pc.model==="wave"||pc.sz==="wave"){
          sz="Wave";
        }else if(pc.model==="falda"){
          var foldMap={pojedyncza:"Flex I",podwojna:"Flex II",potrojna:"Flex III",plaska:"Fa\u0142da P\u0142aska",studio:"Fa\u0142da Studio"};
          sz=pc.foldType?foldMap[pc.foldType]||("Fa\u0142da "+pc.foldType):"Fa\u0142da";
        }else if(pc.model==="tasma"){
          sz=pc.typMarszczenia||"Smok";
        }else{
          sz="Flex";
        }
        var mars=pc.mars?(Math.round(+pc.mars*100))+"%":"150%";
        var split=pc.split||"unequal";
        var splitDesc="-";
        if(split==="left") splitDesc="Lewa";
        else if(split==="right") splitDesc="Prawa";
        else if(split==="equal"){var tw2=par.wCm||0;splitDesc="Kurtyna "+Math.floor(tw2/2)+" + "+Math.ceil(tw2/2)+" cm";}
        else splitDesc=(pc.leftW||0)+"cm + "+(pc.rightW||0)+"cm";
        var bottomMap={single:"Pojedynczy",double:"Podw\xf3jny",overlock:"Overlock",tape:"O\u0142owianka"};
        var bottomDesc=(bottomMap[pc.bottomType||"single"]||"Pojedynczy")+(pc.bottomSize?" "+pc.bottomSize+"cm":"");
        rows.push({
          room:r.name,win:w.name,
          type:lblDisp,
          fabric:prod.fabName||(prod.fabManName||"tkanina"),
          prod:fabObj?fabObj.prod:"-",
          fabW:prod.fabW||prod.fabManW||"-",
          kolor:pc.kolor||"-",
          metry:metry,
          hCm:par.hCm||"-",
          wCm:par.wCm||"-",
          szStyle:sz,marszczenie:mars,
          tasma:(pc.model==="tasma"||pc.model==="falda")?(pc.szerokosc_tasmy||8)+" cm":"-",
          haczyk:(pc.model==="tasma"||pc.model==="falda")?(pc.wysokosc_haczyka!=null?pc.wysokosc_haczyka:2.5)+" cm":"-",
          split:splitDesc,bottom:bottomDesc,
          glide:sz==="Wave"?"Odst\u0119p "+(pc.glideGap||8)+" cm":"-",
          leadInSides:pc.leadInSides?"tak":"nie",
          podszewka:pc.podszewka==="tak"?"TAK":"nie",
          tasmaNaStojaco:pc.tasmaNaStojaco?"tak":"nie",
          note:prod.note||""
        });
      });
    });
  });
  return rows;
}


// Generic HTML→PDF via print dialog (window.print in iframe)
export const LOGO_PDF_G ="data:image/png;base64,";
export const BANNER_PDF_G ="data:image/jpeg;base64,";
export function openPDFWindow(htmlContent, title, opts){
  opts=opts||{};
  var pageSize=opts.landscape?"A4 landscape":"A4";
  // Marginesy dajemy paddingiem body, a @page ma margin:0 — dzięki temu przeglądarka
  // nie drukuje własnych nagłówków/stopek (data, tytuł, adres blob:, numer strony).
  var bodyPad=opts.landscape?"12mm 14mm":"14mm 12mm";
  var printReady=htmlContent.replace("</head>",
    "<style>@media print{@page{size:"+pageSize+";margin:0;}body{padding:"+bodyPad+" !important;margin:0;}}</style>\n"+
    "<script>window.onload=function(){setTimeout(function(){window.print();},600);};<\/script>\n"+
    "</head>"
  );
  var blob=new Blob([printReady],{type:"text/html;charset=utf-8"});
  var url=URL.createObjectURL(blob);
  var w=window.open(url,"_blank","width=960,height=750");
  if(!w){alert("Przegl\u0105darka zablokowa\u0142a okno popup. Zezw\xf3l na popupy dla tej strony.");}
  setTimeout(function(){URL.revokeObjectURL(url);},60000);
}

export function makeTableHTML(headers, rows, caption, colWidths){
  var colgroupHTML="";
  if(colWidths&&colWidths.length){
    colgroupHTML="<colgroup>"+colWidths.map(function(w){return w?"<col style=\"width:"+w+"\">":"<col>";}).join("")+"</colgroup>";
  }
  var headerHTML=headers.map(function(h){return "<th>"+h+"</th>";}).join("");
  var rowsHTML=rows.map(function(r){
    return "<tr>"+r.map(function(c){return "<td>"+c+"</td>";}).join("")+"</tr>";
  }).join("");
  return "<table>"+colgroupHTML+"<caption>"+caption+"</caption><thead><tr>"+headerHTML+"</tr></thead><tbody>"+rowsHTML+"</tbody></table>";
}

